PriceView getPrice(Tenant tenant, Sku sku, long minVersion) {
    authorize(tenant, sku);
    Optional<PriceView> hit = cache.get(tenant, sku);
    if (hit.isPresent() && hit.get().version() >= minVersion)
        return hit.get(); // Другим клиентам свежесть не обещана.
    PriceView row = primaryDb.readCommitted(tenant, sku);
    if (row.version() < minVersion) throw new RetryableConsistencyError();
    cache.fillIfNotOlder(tenant, sku, row);
    return row;
}
// UPDATE возвращает version из SQL; клиент несёт её в следующий GET.
